"use client"

import * as React from "react"
import { Combobox as ComboboxPrimitive } from "@base-ui/react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group"
import { ChevronDownIcon, ChevronsUpDownIcon, XIcon, CheckIcon } from "lucide-react"

export const ComboboxContext: React.Context<{
  chipsRef: React.RefObject<Element | null> | null
  multiple: boolean
}> = React.createContext<{
  chipsRef: React.RefObject<Element | null> | null
  multiple: boolean
}>({
  chipsRef: null,
  multiple: false,
})

import "@/styles/selection.styles.css"

const Combobox = ComboboxPrimitive.Root

function ComboboxValue({ ...props }: ComboboxPrimitive.Value.Props) {
  return <ComboboxPrimitive.Value data-slot="combobox-value" {...props} />
}

type ComboboxTriggerProps = ComboboxPrimitive.Trigger.Props & {
  /** Whether to render the built-in chevron icon. Defaults to `true`. */
  showIcon?: boolean
  /** Icon to render when `showIcon` is true. Defaults to `ChevronDownIcon`. */
  icon?: React.ReactNode
}

function ComboboxTrigger({
  className,
  children,
  showIcon = true,
  icon,
  ...props
}: ComboboxTriggerProps) {
  return (
    <ComboboxPrimitive.Trigger
      data-slot="combobox-trigger"
      className={cn("cn-combobox-trigger", className)}
      {...props}
    >
      {children}
      {showIcon && (icon ?? <ChevronDownIcon aria-hidden="true" />)}
    </ComboboxPrimitive.Trigger>
  )
}

function ComboboxClear({ className, ...props }: ComboboxPrimitive.Clear.Props) {
  return (
    <ComboboxPrimitive.Clear
      aria-label="Clear selection"
      tabIndex={0}
      data-slot="combobox-clear"
      className={cn("cn-selection-action cn-combobox-clear", className)}
      {...props}
    >
      <XIcon className="pointer-events-none" />
    </ComboboxPrimitive.Clear>
  )
}

function ComboboxInput({
  className,
  children,
  disabled,
  showTrigger = true,
  showClear = false,
  autoFocus = true,
  startAddon,
  onChange,
  ...props
}: ComboboxPrimitive.Input.Props & {
  showTrigger?: boolean
  showClear?: boolean
  /**
   * Whether the input receives focus when the popup opens.
   * Defaults to `true` — standard combobox UX so the user can type immediately.
   * Pass `false` to opt out (e.g. on mobile where auto-keyboard is unwanted).
   */
  autoFocus?: boolean
  /**
   * Content rendered at the leading edge of the input.
   * Typically an icon like `<SearchIcon />` to hint the input is for searching.
   */
  startAddon?: React.ReactNode
}) {
  // Track the input's current text locally so we can show/hide the clear button
  // whenever the user has typed something, independent of Base UI's selection-based
  // visibility on ComboboxClear (which only shows when a value is selected).
  const [hasValue, setHasValue] = React.useState(false)

  const handleChange: NonNullable<ComboboxPrimitive.Input.Props["onChange"]> = (event) => {
    setHasValue(event.currentTarget.value !== "")
    onChange?.(event)
  }

  return (
    <ComboboxPrimitive.InputGroup
      render={<InputGroup />}
      className={cn("cn-combobox-control w-auto", className)}
    >
      {startAddon && (
        <InputGroupAddon
          align="inline-start"
          className="text-muted-foreground [&_svg:not([class*='size-'])]:size-4"
        >
          {startAddon}
        </InputGroupAddon>
      )}
      <ComboboxPrimitive.Input
        render={<InputGroupInput nativeInput />}
        disabled={disabled}
        autoFocus={autoFocus}
        onChange={handleChange}
        {...props}
      />
      <InputGroupAddon align="inline-end">
        {showClear && (
          <ComboboxClear
            disabled={disabled}
            keepMounted
            className={hasValue ? "cn-selection-query-clear" : undefined}
            onClick={() => setHasValue(false)}
          />
        )}
        {showTrigger && (
          <Button
            size="icon-xs"
            variant="ghost"
            render={<ComboboxTrigger />}
            data-slot="input-group-button"
            className="cn-selection-action"
            aria-label="Show options"
            disabled={disabled}
          />
        )}
      </InputGroupAddon>
      {children}
    </ComboboxPrimitive.InputGroup>
  )
}

function ComboboxContent({
  className,
  children,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  anchor,
  ...props
}: ComboboxPrimitive.Popup.Props &
  Pick<
    ComboboxPrimitive.Positioner.Props,
    "side" | "align" | "sideOffset" | "alignOffset" | "anchor"
  >) {
  return (
    <ComboboxPrimitive.Portal>
      <ComboboxPrimitive.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        anchor={anchor}
        className="cn-selection-positioner"
      >
        <ComboboxPrimitive.Popup
          data-slot="combobox-content"
          data-chips={!!anchor}
          className={cn("cn-selection-popup cn-combobox-popup", className)}
          {...props}
        >
          {children}
        </ComboboxPrimitive.Popup>
      </ComboboxPrimitive.Positioner>
    </ComboboxPrimitive.Portal>
  )
}

function ComboboxList({ className, ...props }: ComboboxPrimitive.List.Props) {
  return (
    <ComboboxPrimitive.List
      data-slot="combobox-list"
      className={cn("cn-selection-list cn-combobox-list", className)}
      {...props}
    />
  )
}

type ComboboxItemProps = ComboboxPrimitive.Item.Props & {
  /**
   * Where to render the selected-state check indicator.
   * - `'right'` (default): indicator occupies a trailing flex slot.
   * - `'left'`: indicator occupies a leading flex slot.
   */
  checkPosition?: "left" | "right"
}

function ComboboxItem({
  className,
  children,
  checkPosition = "right",
  ...props
}: ComboboxItemProps) {
  return (
    <ComboboxPrimitive.Item
      data-slot="combobox-item"
      data-check-position={checkPosition}
      className={cn("cn-selection-item", className)}
      {...props}
    >
      <div className="cn-selection-text">{children}</div>
      <span className="cn-selection-indicator" aria-hidden="true">
        <ComboboxPrimitive.ItemIndicator>
          <CheckIcon />
        </ComboboxPrimitive.ItemIndicator>
      </span>
    </ComboboxPrimitive.Item>
  )
}

function ComboboxGroup({ className, ...props }: ComboboxPrimitive.Group.Props) {
  return (
    <ComboboxPrimitive.Group
      data-slot="combobox-group"
      className={cn("cn-selection-group", className)}
      {...props}
    />
  )
}

function ComboboxLabel({ className, ...props }: ComboboxPrimitive.GroupLabel.Props) {
  return (
    <ComboboxPrimitive.GroupLabel
      data-slot="combobox-label"
      className={cn("cn-selection-label", className)}
      {...props}
    />
  )
}

function ComboboxCollection({ ...props }: ComboboxPrimitive.Collection.Props) {
  return <ComboboxPrimitive.Collection data-slot="combobox-collection" {...props} />
}

function ComboboxEmpty({ className, ...props }: ComboboxPrimitive.Empty.Props) {
  return (
    <ComboboxPrimitive.Empty
      data-slot="combobox-empty"
      className={cn("cn-selection-empty", className)}
      {...props}
    />
  )
}

function ComboboxStatus({ className, ...props }: ComboboxPrimitive.Status.Props) {
  return (
    <ComboboxPrimitive.Status
      data-slot="combobox-status"
      className={cn("cn-selection-status", className)}
      {...props}
    />
  )
}

function ComboboxRow({ className, ...props }: ComboboxPrimitive.Row.Props) {
  return <ComboboxPrimitive.Row data-slot="combobox-row" className={cn(className)} {...props} />
}

function ComboboxSeparator({ className, ...props }: ComboboxPrimitive.Separator.Props) {
  return (
    <ComboboxPrimitive.Separator
      data-slot="combobox-separator"
      className={cn("cn-selection-separator", className)}
      {...props}
    />
  )
}

function ComboboxChips({
  className,
  children,
  startAddon,
  ...props
}: ComboboxPrimitive.Chips.Props & {
  startAddon?: React.ReactNode
}): React.ReactElement {
  const { chipsRef } = React.useContext(ComboboxContext)

  return (
    <ComboboxPrimitive.Chips
      className={cn("cn-combobox-chips", className)}
      data-slot="combobox-chips"
      ref={chipsRef as React.Ref<HTMLDivElement> | null}
      {...props}
    >
      {startAddon && (
        <div aria-hidden="true" className="cn-selection-start" data-slot="combobox-start-addon">
          {startAddon}
        </div>
      )}
      {children}
    </ComboboxPrimitive.Chips>
  )
}

function ComboboxChip({
  children,
  removeProps,
  className,
  ...props
}: ComboboxPrimitive.Chip.Props & {
  removeProps?: ComboboxPrimitive.ChipRemove.Props
}): React.ReactElement {
  return (
    <ComboboxPrimitive.Chip
      className={cn("cn-combobox-chip", className)}
      data-slot="combobox-chip"
      {...props}
    >
      <span className="cn-combobox-chip-text">{children}</span>
      <ComboboxChipRemove
        aria-label={
          props["aria-label"]
            ? `Remove ${props["aria-label"]}`
            : typeof children === "string"
              ? `Remove ${children}`
              : "Remove"
        }
        {...removeProps}
      />
    </ComboboxPrimitive.Chip>
  )
}

function ComboboxChipRemove({
  className,
  ...props
}: ComboboxPrimitive.ChipRemove.Props): React.ReactElement {
  return (
    <ComboboxPrimitive.ChipRemove
      aria-label="Remove"
      className={cn("cn-selection-action cn-combobox-chip-remove", className)}
      data-slot="combobox-chip-remove"
      {...props}
    >
      <XIcon />
    </ComboboxPrimitive.ChipRemove>
  )
}

function ComboboxChipsInput({
  className,
  size,
  ...props
}: Omit<ComboboxPrimitive.Input.Props, "size"> & {
  size?: "sm" | "default" | "lg" | number
  ref?: React.Ref<HTMLInputElement>
}): React.ReactElement {
  const sizeValue = (size ?? "default") as "sm" | "default" | "lg" | number

  return (
    <ComboboxPrimitive.Input
      className={cn("cn-combobox-chips-input", className)}
      data-size={typeof sizeValue === "string" ? sizeValue : undefined}
      data-slot="combobox-chips-input"
      size={typeof sizeValue === "number" ? sizeValue : undefined}
      {...props}
    />
  )
}
function useComboboxAnchor() {
  return React.useRef<HTMLDivElement | null>(null)
}

const useComboboxFilter: typeof ComboboxPrimitive.useFilter = ComboboxPrimitive.useFilter

// Re-exported for callers that want the Base UI up/down chevron convention.
export { ChevronsUpDownIcon as ComboboxUpDownIcon }

export {
  Combobox,
  ComboboxInput,
  ComboboxContent,
  ComboboxContent as ComboboxPopup,
  ComboboxList,
  ComboboxItem,
  ComboboxGroup,
  ComboboxLabel,
  ComboboxLabel as ComboboxGroupLabel,
  ComboboxCollection,
  ComboboxEmpty,
  ComboboxStatus,
  ComboboxRow,
  ComboboxSeparator,
  ComboboxChips,
  ComboboxChip,
  ComboboxChipsInput,
  ComboboxChipRemove,
  ComboboxTrigger,
  ComboboxClear,
  ComboboxValue,
  useComboboxAnchor,
  useComboboxFilter,
}

/* Selection/search anatomy. Public theme roles remain owned by the V2 foundation. */
@layer components {
  .cn-select-trigger {
    --selection-height: 36;
    --selection-inset: 12;
    --selection-type: 14;
    --selection-leading: 20;
    display: inline-flex;
    box-sizing: border-box;
    align-items: center;
    justify-content: space-between;
    gap: calc(6 * var(--cn-unit));
    width: fit-content;
    max-width: 100%;
    min-width: 0;
    height: calc(var(--selection-height) * var(--cn-unit));
    padding: 0 calc(var(--selection-inset) * var(--cn-unit) - 1px);
    border: 1px solid var(--cn-border-control);
    border-radius: var(--cn-radius-control);
    background: var(--cn-surface);
    color: var(--cn-text);
    font-size: calc(var(--selection-type) * var(--cn-unit));
    line-height: calc(var(--selection-leading) * var(--cn-unit));
    font-weight: 500;
    text-align: start;
    transition:
      border-color var(--cn-duration-fast) var(--cn-ease-standard),
      background-color var(--cn-duration-fast) var(--cn-ease-standard);
  }
  .cn-select-trigger[data-size="sm"] {
    --selection-height: 32;
    --selection-inset: 10;
    --selection-type: 13;
    --selection-leading: 18;
  }
  .cn-select-trigger[data-size="lg"] {
    --selection-height: 40;
    --selection-inset: 14;
  }
  .cn-select-value {
    display: flex;
    flex: 1;
    align-items: center;
    gap: calc(6 * var(--cn-unit));
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    text-align: start;
  }
  .cn-select-trigger[data-placeholder] {
    color: var(--cn-text-muted);
    font-weight: 400;
  }
  .cn-select-icon {
    flex-shrink: 0;
    color: var(--cn-text-muted);
  }
  .cn-select-trigger svg,
  .cn-combobox-trigger svg,
  .cn-selection-start svg,
  .cn-selection-item :where(svg:not([class*="size-"])) {
    flex-shrink: 0;
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    pointer-events: none;
  }
  .cn-select-trigger[data-popup-open],
  :is(.cn-autocomplete-control, .cn-combobox-control):has(input[data-popup-open]),
  .cn-combobox-chips:has(input[data-popup-open]) {
    border-color: var(--cn-border-active);
  }
  .cn-select-trigger:is([aria-invalid="true"], [data-invalid]) {
    border-color: var(--cn-status-destructive-border);
  }
  .cn-select-trigger[data-readonly] {
    background: var(--cn-surface-muted);
  }
  .cn-select-trigger:is(:disabled, [data-disabled]) {
    color: var(--cn-text-disabled);
    background: var(--cn-surface-disabled);
    border-color: var(--cn-border-disabled);
    cursor: not-allowed;
  }
  .cn-select-trigger:is(:disabled, [data-disabled]) .cn-select-icon {
    color: inherit;
  }
  .cn-select-trigger:focus-visible {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-selection-positioner {
    isolation: isolate;
    z-index: 50;
  }
  .cn-selection-popup {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: min(calc(144 * var(--cn-unit)), var(--available-width));
    width: var(--anchor-width);
    max-width: var(--available-width);
    max-height: min(var(--available-height), calc(368 * var(--cn-unit)));
    overflow: hidden;
    border: 1px solid var(--cn-border);
    border-radius: var(--cn-radius-card);
    background: var(--cn-surface-popup);
    color: var(--cn-text);
    box-shadow: var(--cn-shadow-popup);
    transform-origin: var(--transform-origin);
    transition:
      opacity var(--cn-duration-popup) var(--cn-ease-enter),
      scale var(--cn-duration-popup) var(--cn-ease-enter);
  }
  .cn-selection-popup:is([data-starting-style], [data-ending-style]) {
    opacity: 0;
    scale: 0.98;
  }
  .cn-selection-popup[data-ending-style] {
    transition-duration: var(--cn-duration-fast);
    transition-timing-function: var(--cn-ease-exit);
  }
  /* Item-aligned Select positioning measures the popup; do not scale that geometry. */
  .cn-select-popup[data-align-trigger="true"] {
    scale: none;
    transition: opacity var(--cn-duration-fast);
  }
  .cn-select-popup {
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  .cn-selection-list {
    box-sizing: border-box;
    min-height: 0;
    padding: calc(4 * var(--cn-unit));
    scroll-padding-block: calc(4 * var(--cn-unit));
    outline: none;
  }
  .cn-selection-scroll {
    display: flex;
    flex-direction: column;
    max-height: inherit;
    flex: 1;
    min-height: 0;
    width: 100%;
    overflow: hidden;
  }
  .cn-selection-scroll > [data-slot="scroll-area-viewport"] {
    flex: 1;
    min-height: 0;
    max-height: inherit;
  }
  .cn-combobox-list {
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  .cn-combobox-popup > .cn-input-group {
    margin: calc(4 * var(--cn-unit));
    flex-shrink: 0;
  }
  .cn-selection-item {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: calc(8 * var(--cn-unit));
    min-width: 0;
    min-height: calc(32 * var(--cn-unit));
    width: 100%;
    padding: calc(6 * var(--cn-unit)) calc(8 * var(--cn-unit));
    border-radius: var(--cn-radius-item);
    color: var(--cn-text);
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
    font-weight: 400;
    overflow-wrap: anywhere;
    cursor: default;
    user-select: none;
    outline: none;
  }
  .cn-selection-text {
    display: flex;
    flex: 1;
    align-items: center;
    gap: calc(8 * var(--cn-unit));
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .cn-selection-indicator {
    display: flex;
    flex: 0 0 calc(16 * var(--cn-unit));
    align-self: center;
    align-items: center;
    justify-content: center;
    margin-inline-start: auto;
  }
  .cn-selection-indicator svg {
    width: calc(12 * var(--cn-unit));
    height: calc(12 * var(--cn-unit));
  }
  [data-check-position="left"] > .cn-selection-indicator {
    order: -1;
    margin-inline-start: 0;
  }
  .cn-selection-item[data-selected] {
    background: var(--cn-surface-selected);
    font-weight: 500;
  }
  .cn-selection-item[data-highlighted] {
    background: var(--cn-surface-hover);
  }
  /* Selection keeps its check; the inset edge marks navigation even on a selected row. */
  .cn-selection-item[data-highlighted] {
    box-shadow: inset calc(2 * var(--cn-unit)) 0 var(--cn-border-active);
  }
  .cn-selection-item[data-selected][data-highlighted] {
    background: var(--cn-surface-selected);
  }
  .cn-selection-item[data-disabled] {
    color: var(--cn-text-disabled);
    pointer-events: none;
  }
  .cn-selection-item[data-disabled][data-selected] {
    background: var(--cn-surface-disabled);
  }
  .cn-selection-group + .cn-selection-group {
    margin-block-start: calc(4 * var(--cn-unit));
  }
  .cn-selection-label {
    padding: calc(8 * var(--cn-unit));
    color: var(--cn-text-muted);
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
    font-weight: 500;
  }
  .cn-selection-meta {
    flex-shrink: 0;
    margin-inline-start: auto;
    color: var(--cn-text-muted);
    font-family: inherit;
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
    font-weight: 400;
  }
  .cn-selection-separator {
    height: 1px;
    margin: calc(4 * var(--cn-unit));
    background: var(--cn-border-subtle);
    pointer-events: none;
  }
  .cn-selection-empty,
  .cn-selection-status {
    padding: calc(12 * var(--cn-unit));
    color: var(--cn-text-muted);
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
    overflow-wrap: anywhere;
  }
  .cn-selection-empty {
    text-align: center;
  }
  .cn-selection-empty:empty,
  .cn-selection-status:empty {
    margin: 0;
    padding: 0;
  }
  .cn-selection-status {
    flex-shrink: 0;
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
  }
  .cn-select-scroll {
    position: sticky;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: calc(24 * var(--cn-unit));
    width: 100%;
    background: var(--cn-surface-popup);
  }
  .cn-select-scroll-up {
    top: 0;
  }
  .cn-select-scroll-down {
    bottom: 0;
  }
  .cn-select-scroll svg {
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
  }
  .cn-selection-start {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    padding-inline-start: calc(11 * var(--cn-unit));
    color: var(--cn-text-muted);
    pointer-events: none;
  }
  .cn-autocomplete-control:has(.cn-selection-start) .cn-input {
    padding-inline-start: calc(6 * var(--cn-unit));
  }
  .cn-selection-action {
    box-sizing: border-box;
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    width: calc(28 * var(--cn-unit));
    height: calc(28 * var(--cn-unit));
    padding: 0;
    border: 0;
    border-radius: var(--cn-radius-item);
    background: transparent;
    color: var(--cn-text-muted);
    cursor: pointer;
  }
  .cn-selection-action svg {
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    pointer-events: none;
  }
  /* Inset contours stay complete inside compact composite boundaries. */
  .cn-selection-action:focus-visible,
  .cn-combobox-chip:focus-visible {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: -2px;
  }
  .cn-selection-action:is(:disabled, [data-disabled], [aria-disabled="true"]) {
    color: var(--cn-text-disabled);
    cursor: default;
  }
  .cn-autocomplete-control > .cn-selection-action {
    margin-inline-end: calc(3 * var(--cn-unit));
  }
  .cn-autocomplete-control:has([data-slot="autocomplete-clear"])
    > [data-slot="autocomplete-trigger"] {
    display: none;
  }
  .cn-combobox-clear:not([data-visible]):not(.cn-selection-query-clear) {
    display: none;
  }
  .cn-combobox-control:has(.cn-combobox-clear:is([data-visible], .cn-selection-query-clear))
    .cn-combobox-trigger {
    display: none;
  }
  :is(.cn-autocomplete-control, .cn-combobox-control):has(input[readonly]) .cn-selection-action {
    color: var(--cn-text-disabled);
  }
  .cn-combobox-chips {
    --chips-height: 36;
    --chip-height: 28;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: calc(4 * var(--cn-unit));
    width: 100%;
    min-width: 0;
    min-height: calc(var(--chips-height) * var(--cn-unit));
    padding: calc(3 * var(--cn-unit));
    border: 1px solid var(--cn-border-control);
    border-radius: var(--cn-radius-control);
    background: var(--cn-surface);
    color: var(--cn-text);
  }
  .cn-combobox-chips:has([data-size="sm"]) {
    --chips-height: 32;
    --chip-height: 24;
  }
  .cn-combobox-chips:has([data-size="lg"]) {
    --chips-height: 40;
  }
  .cn-combobox-chips:has(input:focus-visible) {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-combobox-chips:has(input[readonly]) {
    background: var(--cn-surface-muted);
  }
  :is(.cn-autocomplete-control, .cn-combobox-control, .cn-combobox-chips):has(
    input:is([aria-invalid="true"], [data-invalid])
  ) {
    border-color: var(--cn-status-destructive-border);
  }
  :is(.cn-autocomplete-control, .cn-combobox-control, .cn-combobox-chips):has(input:disabled) {
    color: var(--cn-text-disabled);
    border-color: var(--cn-border-disabled);
    background: var(--cn-surface-disabled);
  }
  .cn-combobox-chip {
    display: inline-flex;
    align-items: center;
    max-width: 100%;
    min-width: 0;
    min-height: calc(var(--chip-height) * var(--cn-unit));
    padding-inline-start: calc(8 * var(--cn-unit));
    border-radius: var(--cn-radius-item);
    background: var(--cn-surface-selected);
    color: var(--cn-text);
    font-size: calc(12 * var(--cn-unit));
    line-height: calc(18 * var(--cn-unit));
    font-weight: 500;
  }
  .cn-combobox-chip-text {
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .cn-combobox-chip-remove {
    align-self: stretch;
    height: auto;
    min-height: calc(var(--chip-height) * var(--cn-unit));
    margin-inline-start: calc(4 * var(--cn-unit));
  }
  .cn-combobox-chip[data-disabled] {
    color: var(--cn-text-disabled);
    background: var(--cn-surface-disabled);
  }
  .cn-combobox-chips-input {
    flex: 1;
    box-sizing: border-box;
    min-width: calc(64 * var(--cn-unit));
    width: 0;
    height: calc(var(--chips-height) * var(--cn-unit) - 8 * var(--cn-unit));
    padding-inline: calc(8 * var(--cn-unit));
    border: 0;
    background: transparent;
    color: inherit;
    font-size: calc(14 * var(--cn-unit));
    line-height: calc(20 * var(--cn-unit));
    outline: none;
  }
  .cn-combobox-chips-input::placeholder {
    color: var(--cn-text-muted);
    opacity: 1;
  }
  .cn-command-input {
    padding: calc(8 * var(--cn-unit));
  }
  .cn-command-list {
    max-height: calc(320 * var(--cn-unit));
  }
  .cn-command-empty:not(:empty) {
    padding-block: calc(24 * var(--cn-unit));
  }
}
@media (hover: hover) {
  @layer components {
    .cn-select-trigger:not(
        :disabled,
        [data-disabled],
        [aria-invalid="true"],
        [data-invalid],
        [data-popup-open]
      ):hover {
      border-color: var(--cn-border-hover);
    }
    .cn-selection-item:not([data-disabled], [data-selected]):hover {
      background: var(--cn-surface-hover);
    }
    .cn-selection-action:not(:disabled, [data-disabled], [aria-disabled="true"]):hover {
      background: var(--cn-surface-hover);
      color: var(--cn-text);
    }
  }
}
@media (max-width: 40rem), (pointer: coarse) {
  @layer components {
    .cn-combobox-chips-input {
      font-size: calc(16 * var(--cn-unit));
      line-height: calc(24 * var(--cn-unit));
    }
  }
}
@media (pointer: coarse) {
  @layer components {
    .cn-select-trigger {
      height: max(calc(var(--selection-height) * var(--cn-unit)), 44px);
    }
    .cn-selection-item {
      min-height: 44px;
    }
    .cn-selection-action {
      min-width: 44px;
      min-height: 44px;
    }
    .cn-autocomplete-control:has(.cn-selection-action),
    .cn-combobox-control:has(.cn-selection-action) {
      min-height: 52px;
    }
    .cn-combobox-chip {
      min-height: 44px;
    }
    .cn-combobox-chips {
      gap: calc(8 * var(--cn-unit));
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .cn-select-trigger,
  .cn-selection-popup {
    transition: none;
    scale: none;
  }
}
@media (forced-colors: active) {
  .cn-select-trigger:focus-visible,
  .cn-selection-action:focus-visible,
  .cn-combobox-chip:focus-visible,
  .cn-combobox-chips:has(input:focus-visible) {
    outline-color: Highlight;
  }
  .cn-selection-item[data-highlighted] {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
  .cn-selection-item[data-selected] {
    border-inline-start: 2px solid CanvasText;
  }
}
